@st.cache_data(show_spinner=False)
def load_data():
    raw = json.loads(zlib.decompress(base64.b64decode(EMBEDDED_DATA)))
    files = {name: pd.read_csv(io.StringIO(text)) for name, text in raw.items()}
    all_df = files["saintmarc_all.csv"].copy()
    text_df = files["saintmarc_text.csv"]
    prepared = files["saintmarc_wakati.csv"].copy()
    if not all_df[text_df.columns].equals(text_df):
        raise ValueError("saintmarc_all.csv and saintmarc_text.csv are inconsistent.")
    all_df["response_id"] = np.arange(1, len(all_df) + 1)
    all_df["_occ"] = all_df.groupby("Q3_2", dropna=False).cumcount()
    prepared["_occ"] = prepared.groupby("Q3_2", dropna=False).cumcount()
    # Repeated comments are matched by occurrence order, never a many-to-many join.
    prepared = prepared.merge(
        all_df[["Q3_2", "_occ", "response_id", "AGE", "SEX"]],
        on=["Q3_2", "_occ"], how="left", sort=False, validate="one_to_one",
    )
    if prepared["response_id"].isna().any():
        raise ValueError("A prepared comment could not be matched to the original data.")
    all_df["age_group"] = pd.cut(all_df.AGE, AGE_BINS, labels=AGE_JA)
    prepared["age_group"] = pd.cut(prepared.AGE, AGE_BINS, labels=AGE_JA)
    prepared["wakati"] = prepared.wakati.fillna("")
    return all_df, prepared


def token_lists(frame, stop):
    stop = set(stop)
    return [[t for t in s.split() if t not in stop] for s in frame.wakati]


def word_table(tokens):
    counts = Counter(t for row in tokens for t in row)
    docs = Counter(t for row in tokens for t in set(row))
    return pd.DataFrame(
        [{"word": w, "frequency": n, "documents": docs[w]} for w, n in counts.most_common()],
        columns=["word", "frequency", "documents"],
    )


@st.cache_data(show_spinner=False)
def fit_topics(docs, k):
    """Fit on nonempty BoW rows only; preserve the exact original row positions."""
    vectorizer = CountVectorizer(tokenizer=str.split, preprocessor=None,
                                 token_pattern=None, lowercase=False,
                                 min_df=3, max_df=0.8)
    matrix = vectorizer.fit_transform(docs)
    valid = np.asarray(matrix.sum(axis=1)).ravel() > 0
    if valid.sum() < k or matrix.shape[1] < k:
        raise ValueError("Too few usable documents or words for the selected number of topics.")
    model = LatentDirichletAllocation(n_components=k, max_iter=20,
                                      learning_method="batch", random_state=42,
                                      n_jobs=1, evaluate_every=-1)
    probabilities = model.fit_transform(matrix[valid])
    components = model.components_ / model.components_.sum(axis=1, keepdims=True)
    return probabilities, components, vectorizer.get_feature_names_out(), np.flatnonzero(valid)


