def plot(fig):
    fig.update_layout(template="plotly_white", paper_bgcolor="rgba(0,0,0,0)",
                      plot_bgcolor="rgba(0,0,0,0)", font=dict(family="Noto Sans JP, Meiryo, sans-serif", color="#493E33"),
                      margin=dict(l=12, r=20, t=30, b=25), colorway=COLORS,
                      legend_title_text="")
    st.plotly_chart(fig, width="stretch", config={"displaylogo": False})


def bar(frame, x, y, xlabel, ylabel="", color=COLORS[0], height=430):
    fig = px.bar(frame, x=x, y=y, orientation="h", text_auto=".3~g",
                 labels={x: xlabel, y: ylabel}, color_discrete_sequence=[color], height=height)
    fig.update_yaxes(autorange="reversed")
    plot(fig)


